draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw good bacteria
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw fiber prebiotic
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20 * Math.sin(t), H/2, 10, 0, 2 * Math.PI);
  ctx.fill();

  // Draw feeding action
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t), H/2);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();

  // Draw smile on good bacteria
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 10, 5, 0, Math.PI);
  ctx.stroke();

  ctx.restore();
}
